diff = (lpw - lpl) - 0.1 * gap;
norm = sqrt(mean(diff^2) + 1e-12);
normed_diff = diff / norm;
sigmoid_scale = 2 * sigmoid(alpha * normed_diff) - 1  # squashed to (-1,1)
x_fwd = scale * sigmoid_scale;
x_bwd = -x_fwd;
loss_fwd = -logsigmoid(x_fwd);
loss_bwd = -logsigmoid(x_bwd);
loss = mean((loss_fwd + loss_bwd)/2 weighted by weight)
